def _shingles(s, k):
    s = " ".join(s.lower().split())
    if not s:
        return set()
    if len(s) < k:
        return {s}
    return {s[i:i + k] for i in range(len(s) - k + 1)}

def jaccard(a, b, k=None):
    A, B = (set(a), set(b)) if k is None else (_shingles(a, k), _shingles(b, k))
    union = A | B
    return 1.0 if not union else len(A & B) / len(union)
